expression = "P and not P"   # yahan apna expression likhein (P, Q, and, or, not)

found = []
for P in [True, False]:
    for Q in [True, False]:
        if eval(expression, {}, {"P": P, "Q": Q}):
            found.append((P, Q))

if found:
    print("Satisfiable. True for (P, Q):", found)
else:
    print("Unsatisfiable. No row makes it true.")
